<h1 class="h3">Dealer Credential Activity</h1><p>Credential-management history. Dealer filter uses exact membership ID.</p>
<form method="get" class="row g-2 mb-3" action="<?= site_url('admin/dealer-credential-activity') ?>">
<?php foreach(['agency'=>'Agency ID','dealer'=>'Dealer membership ID','from'=>'From','to'=>'To'] as $key=>$label): ?><div class="col-sm-3"><label class="form-label" for="audit-<?= $key ?>"><?= $label ?></label><input id="audit-<?= $key ?>" class="form-control" type="<?= in_array($key,['from','to'])?'date':'number' ?>" name="<?= $key ?>" value="<?= esc($filters[$key],'attr') ?>"></div><?php endforeach ?>
<div class="col-sm-4"><label class="form-label" for="auditAction">Action</label><select class="form-select" name="action" id="auditAction"><option value="">All actions</option><?php foreach(\App\Services\DealerCredentialHistory::ACTIONS as $action): ?><option <?= $filters['action']===$action?'selected':'' ?>><?= $action ?></option><?php endforeach ?></select></div>
<div class="col-sm-4"><label class="form-label" for="auditRole">Actor role</label><select class="form-select" name="role" id="auditRole"><option value="">All roles</option><?php foreach(['agency','admin','dealer','system'] as $role): ?><option <?= $filters['role']===$role?'selected':'' ?>><?= $role ?></option><?php endforeach ?></select></div><div class="col-sm-4 align-self-end"><button class="btn btn-primary">Filter</button></div></form>
<div class="card p-3"><p><?= $total ?> events</p><div class="table-responsive"><table class="table"><thead><tr><?php foreach(['Date/time','Agency / Dealer','Source / Username','Action / Outcome','Actor','Changes'] as $label): ?><th><?= $label ?></th><?php endforeach ?></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td><?= esc($row['occurred_at']) ?></td><td><?= esc($row['agency_name_snapshot']) ?><small class="d-block">Agency #<?= (int)$row['portal_agency_id'] ?></small><?= esc($row['dealer_name_snapshot']) ?><small class="d-block">Membership #<?= (int)$row['agency_dealer_membership_id'] ?> / Login #<?= (int)$row['dealer_account_id'] ?></small><?php if(can('agencies.edit')): ?><a href="<?= site_url('admin/dealer-logins/'.$row['agency_dealer_membership_id']) ?>">Manage login</a><?php endif ?></td><td><?= esc($row['source_code_snapshot']) ?><br><?= esc($row['username_snapshot']??'Not issued') ?></td><td><?= esc($row['action']) ?><br><?= esc($row['outcome']) ?> <?= esc($row['failure_code']??'') ?></td><td><?= esc(ucfirst($row['actor_role'])) ?><?php $actor=$row['actor_agency_account_id']??$row['actor_admin_id']??$row['actor_dealer_account_id']; if($actor!==null): ?> account #<?= (int)$actor ?><?php endif ?></td><td><?php foreach(['username','enabled','must_change_password','auth_version','temporary_expires_at','revoked_at'] as $field): if($row['before_'.$field]===$row['after_'.$field])continue; ?><div class="small"><?= esc(str_replace('_',' ',$field)) ?>: <?= esc((string)($row['before_'.$field]??'—')) ?> → <?= esc((string)($row['after_'.$field]??'—')) ?></div><?php endforeach ?></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="6">No credential activity matches these filters.</td></tr><?php endif ?></tbody></table></div><nav class="d-flex gap-3"><?php foreach(['Previous'=>$page-1,'Next'=>$page+1] as $label=>$target): if($target<1||$target>$pages)continue; ?><a href="<?= esc(site_url('admin/dealer-credential-activity').'?'.http_build_query($filters+['page'=>$target]),'attr') ?>"><?= $label ?></a><?php endforeach ?><span><?= $page ?> / <?= $pages ?></span></nav></div><?= $this->endSection() ?>
